$F:U\rightarrow\mathbb{R}^d$ is $\mu$-strongly monotone if there exists some $\mu >0$ such that
    \begin{equation}
        \left\langle F(x)-F(y),x-y\right\rangle\geq \mu\|x-y\|^2\hspace{0.5cm}\forall x,y\in U
        \label{muSC}
    \end{equation}
    When $\mu=0$, we call $F$ monotone.

\label{assmpt: l0 l1}
    An operator $F$ is $\alpha$-symmetric $(L_0, L_1)$-Lipschitz if for some $L_0, L_1 \geq 0$ and $\alpha \in (0, 1]$, and for all $x,y\in U$,
    \vspace{-2mm}
    \begin{equation}\label{l0l1 defn}
    \begin{aligned}
        \| F(x) - F(y)\| \leq  
        ( L_0 + L_1 \max_{\theta \in [0, 1]} \left\|F(\theta x + ( 1- \theta) y) \right\|^{\alpha}) \| x- y\|.
    \end{aligned}
    \end{equation}

\label{lem: l0l1 smooth}
    Suppose $F$ is $\alpha$-symmetric $(L_0,L_1)$-Lipschitz. Then if $\alpha=1$
    \begin{equation}
    \begin{aligned}
         \|F(x)&-F(y)\| \leq (L_0+L_1\|F(y)\|)e^{L_1\|x-y\|}\|x-y\|
        \label{a1 l0l1}
    \end{aligned}
    \end{equation}
    and if $\alpha\in (0,1)$,
    \begin{equation}
    \begin{aligned}
        \|&F(x)-F(y)\| 
        \leq (K_0+K_1\|F(y)\|^\alpha + K_2\|x-y\|^{p_\alpha})\|x-y\|
    \end{aligned}
        \label{a small l0l1}
    \end{equation}
    where $p_\alpha=\nicefrac{\alpha}{1-\alpha}$, $K_0=L_0(2^{\alpha p_\alpha}+1)$, $K_1=L_1 2^{\alpha p_\alpha}3^\alpha$ and $K_2=L_1^{p_\alpha/\alpha}2^{\alpha p_\alpha}3^\alpha(1-\alpha)^{p_\alpha}$.

\label{lem:lipschitz analogue}
    For  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 and  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
, if $F$ is $\alpha$-symmetric $(L_0, L_1)$-Lipschitz and we choose the stepsize $\gamma_k$ according to equations (\ref{EG Stepsizes}) and (\ref{Popov stepsizes}) respectively, then the algorithm iterates satisfy
    \vspace{-2mm}
    \begin{equation}
    \gamma_k\|F(\hat{x}_k)-F(\tilde{x}_k)\|\leq  C_\nu \|\hat{x}_k-\tilde{x}_k\| \label{l0l1 half step general}
\end{equation}
where $\tilde{x}_k=x_k$ for  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 and $\tilde{x}_k=\hat{x}_{k-1}$ for  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
, $C_\nu=\nu e^\nu$ if $\alpha=1$, and $C_\nu=\nu$ if $\alpha \in (0,1)$, with $\nu<1$.

\label{lem:EG step lower bound}
Let $F$ be $\alpha$-symmetric $(L_0,L_1)$-Lipschitz.
Fix $x^*\in U^*$ and write
$D_0=\|x_0-x^*\|$.
Suppose the iterates of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 with stepsizes
\eqref{EG Stepsizes} satisfy
$\|x_k-x^*\|\le D_0$ for all $k\ge0$.

Define
\vspace{-3mm}
\begin{align*}
M_1
&:= \|F(x^*)\|+D_0(L_0+L_1\|F(x^*)\|)e^{L_1D_0},\\
M_\alpha
&:= \|F(x^*)\|+D_0\bigl(K_0+K_1\|F(x^*)\|^\alpha +K_2D_0^{p_\alpha}\bigr),\\
A_\alpha
&:= 2K_1+2^{1-\alpha}K_2^{1-\alpha}.
\end{align*}
Then $\gamma_{k, 
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
}\ge\underline{\gamma}$ for all $k\ge0$, where
\begin{equation}\label{EG step lower bound main}
\underline{\gamma} :=
\begin{cases}
\displaystyle\frac{\nu}{L_0+L_1M_1},
& \alpha=1,\\[6pt]
\displaystyle\frac{\nu}{2K_0+A_\alpha M_\alpha^\alpha},
& \alpha\in (0,1)
\end{cases}
\end{equation}

\label{lem:popov step lower bound}
Let $F$ be $\alpha$-symmetric $(L_0,L_1)$-Lipschitz.
Fix $x^*\in U^*$ and define $D_k=\|x_k-x^*\|$,
$R_k=D_k^2+\|x_k-\hat{x}_{k-1}\|^2$, and $F_*=\|F(x^*)\|$

Suppose the iterates of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
 with stepsizes
\eqref{Popov stepsizes} and $C_\nu<1$ satisfy
$R_k\le R_0$ for all $k\ge0$.

For $\alpha=1$, define
\vspace{-2mm}
\begin{align*}
M_{1,\mathrm{PEG}}
&:= \sqrt{2}D_0
    \bigl(L_0+L_1 F_*\bigr) e^{\sqrt{2}L_1D_0}
    + F_*.
\end{align*}
For $\alpha\in (0,1)$, define
\vspace{-2mm}
\begin{align*}
q_\alpha
&:= \frac{\nu^2}
    {(1-\nu)\bigl[K_1+K_2(\nu/K_1)^{p_\alpha}\bigr]}
    +\frac{\nu}{K_1},\\
M_{\alpha,\mathrm{PEG}}
&:= \sqrt{2}D_0
    \bigl(K_0+K_1 F_*^{\alpha}
 +K_2(\sqrt{2}D_0)^{p_\alpha}\bigr)
    +F_*.
\end{align*}
Then, for all $k\ge0$,
\vspace{-2mm}
\begin{equation}\label{popov step lower bound main}
\gamma_{k, 
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
}\ge\underline{\gamma}:=\frac{\nu}{\Delta},
\end{equation}
where
\[
\Delta :=
\begin{cases}
(L_0+L_1M_{1,\mathrm{PEG}})
\exp\!\left(\dfrac{\nu^2e^\nu}{1-\nu e^\nu}\right),
& \alpha=1,\\[6pt]
K_0+(K_1+K_2q_\alpha^{p_\alpha})
M_{\alpha,\mathrm{PEG}}^\alpha,
& \alpha\in (0,1).
\end{cases}
\]

\label{thm: EG monotone}
        Let $F$ be $\alpha$-symmetric $(L_0, L_1)$-Lipschitz and monotone. Additionally let $\bar{x}_K=\frac{\sum_{k=0}^{K-1}\gamma_k\hat{x}_k}{\sum_{k=0}^{K-1}\gamma_k}$ and $x^*\in U^*$. Then the averaged iterates $\bar{x}_K$ of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 with stepsizes given by (\ref{EG Stepsizes}) and $\nu$ chosen so that $C_\nu< 1$  satisfy
         \begin{equation*}
          \texttt{Gap}_{F,B}\left( \bar{x}_K\right)\leq \left( 2+\frac{1}{\sqrt{1-C_\nu^2}} \right)^2\frac{\|x_0-x^*\|^2}{2\underline{\gamma} K}
        \end{equation*}
        where $\underline{\gamma}$ is defined in Lemma~\ref{lem:EG step lower bound} and $B=\{y\in U:\|y-x^*\|^2\leq  (1+(1-C_\nu^2)^{-\nicefrac{1}{2}})^2\|x_0-x^*\|^2\}$. Further, $\bar{x}_K\in B$.

\label{thm: popov monotone}
        Let $F$ be $\alpha$-symmetric $(L_0,L_1)$-Lipschitz and monotone. Additionally, let $\bar{x}_K=\frac{\sum_{k=0}^{K-1}\gamma_k\hat{x}_k}{\sum_{k=0}^{K-1}\gamma_k}$ and $x^*\in U^*$. Then the averaged iterates $\bar{x}_K$ of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
 with stepsize given by (\ref{Popov stepsizes}) and $\nu$ chosen so that $C_\nu\leq\frac{1}{2}$ satisfy 
        \begin{equation*}
            \texttt{Gap}_{F,B}\left( \bar{x}_K\right)\leq \frac{(3+2\sqrt{2})\|x_0-x^*\|^2}{2\underline{\gamma} K}
        \end{equation*}
        where $\underline{\gamma}$ is defined in Lemma~\ref{lem:popov step lower bound} and $B=\left\{y\in U:\|y-x^*\|^2\leq 2\|x_0-x^*\|^2\right\}$. Also, $\bar{x}_K\in B$.

