\label{thm: EG sm}
         Let $F$ be $\alpha$-symmetric $(L_0, L_1)$-Lipschitz and $\mu$-strongly monotone. Then the iterates of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 with stepsizes given by (\ref{EG Stepsizes}) and $\nu$ chosen so that $1-2\nu-\nu^2e^{2\nu}\geq0\text{ if $\alpha = 1$ }$ and $1-\nu-\nu^2\geq0 \text{ if $\alpha \in (0,1)$ }$ satisfy
        \begin{equation*}
            \|x_k-x^*\|^2\leq (1-\underline{\gamma}\mu)^k \|x_0-x^*\|^2
        \end{equation*}
        where $\underline{\gamma}$ is defined in Lemma~\ref{lem:EG step lower bound}.

\label{cor: eg usm}
      Let $F$ be $1$-symmetric $(L_0,L_1)$-Lipschitz and $\mu$-strongly monotone, and $U=\mathbb{R}^n$ (unconstrained case). Then the iterates of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 with stepsizes given by (\ref{EG Stepsizes}) and $\nu$ chosen so that $\nu\approx0.21$ is the solution to the $1-4\nu-2\nu^2e^{2\nu}=0$ satisfy $\|x_{K+1}-x^*\|^2\leq\varepsilon$ after 
     \begin{equation*}
        \left\lfloor \frac{8L_1^2}{\nu^2} \|x_0-x^*\|^2  \right\rfloor+ \left\lceil \frac{2L_0}{\nu\mu}\log\frac{\|x_0-x^*\|^2}{\varepsilon} \right\rceil \text{ iterates.}
    \end{equation*}

\label{thm: popov sm}
        Let $F$ be $\alpha$-symmetric $(L_0,L_1)$-Lipschitz and $\mu$-strongly monotone. Then the iterates of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
 with stepsizes given by (\ref{Popov stepsizes}) and $\nu$ chosen so that $1-2\nu-4C_\nu^2\geq 0$ satisfy
        \begin{equation*}
           R_k\leq (1-\underline{\gamma}\mu)^kR_0
        \end{equation*}
        where $R_k=\|x_k-x^*\|^2+\|x_k-\hat{x}_{k-1}\|^2$  and $\underline{\gamma}$ is defined in Lemma~\ref{lem:popov step lower bound}.

For $a,b\in\mathbb{R}^d$ and $\beta> 0$ we have
    \begin{equation}
        \|a+b\|^2 \leq(1+\beta^{-1})\|a\|^2+(1+\beta)\|b\|^2 \label{full young}
    \end{equation}
    When $\beta=1$, we have
    \begin{equation}
        \|a+b\|^2\leq 2\|a\|^2+2\|b\|^2 \label{young ineq}
    \end{equation}
    We can also rearrange \eqref{full young} to obtain
    \begin{equation}
        -\|a\|^2\leq-\frac{1}{1+\beta}\|a+b\|^2+\frac{1}{\beta}\|b\|^2
        \label{Young-like}
    \end{equation}

For $a,b\in\mathbb{R}$, we have
    \begin{equation}
        2ab\leq a^2+b^2 \label{trivial ineq}
    \end{equation}

For $a,b\in\mathbb{R}^d$, we have
    \begin{equation}
        \left\langle a,b\right\rangle\leq \|a\|\|b\|\label{cauchy-schwarz}
    \end{equation}

Given a nonempty convex closed set $U\subset \mathbb{R}^d$, the projection operator $P_U$ satisfies 
     \begin{align}
        \|P_U(x)-P_U(y)\| \leq \|x-y\| \hspace{0.5cm}&\forall x,y\in\mathbb{R}^d        \label{Nonexpansive} \\
        \left\langle x-P_U(x),u-P_U(x)\right\rangle\leq 0 \hspace{0.5cm}&\forall u\in U, x\in\mathbb{R}^d \label{proj inprd} \\
        \|u-P_U(x)\|^2\leq \|u-x\|^2-\|x-P_U(x)\|^2 \hspace{0.5cm}&\forall u\in U, x\in\mathbb{R}^d \label{proj norm diff}
    \end{align}

If $F:U\rightarrow \mathbb{R}^d$ is a $\mu$-strongly monotone  $\alpha$-symmetric $(L_0,L_1)$-Lipschitz operator, then for any $x\in U$
    \begin{equation}
        \mu\leq \begin{cases}
            L_0+L_1\|F(x)\| &\text{ if $\alpha = 1$ } \\
             K_0+K_1\|F(x)\|^\alpha &\text{ if $\alpha \in (0,1)$ }
        \end{cases}  \label{mu L0 L1}   
    \end{equation}

From strong monotonicity and the Cauchy-Schwarz Inequality, we have
    \begin{align*}
    \mu\|x-y\|^2 &\overset{(\ref{muSC})}{\leq} \left\langle F(x)-F(y),x-y\right\rangle \\
    &\overset{(\ref{cauchy-schwarz})}{\leq}\|F(x)-F(y)\|\|x-y\|  \\
    \end{align*}
    From here, we split into two cases depending on $\alpha$. First, if $\alpha =1$, we have
    \begin{align*}
   \mu\|x-y\|^2 &\overset{(\ref{a1 l0l1})}{\leq} (L_0+L_1\|F(y)\|)\exp(L_1\|x-y\|)\|x-y\|^2 \\
    \Rightarrow \mu&\leq (L_0+L_1\|F(y)\|)\exp(L_1\|x-y\|)
\end{align*}
while if $\alpha \in(0,1)$, we have
\begin{align*}
    \mu\|x-y\|^2  &\leq(K_0+K_1\|F(y)\|^\alpha + K_2\|x-y\|^{\alpha/(1-\alpha)})\|x-y\|^2 \\
    \Rightarrow \mu&\leq (K_0+K_1\|F(y)\|^\alpha + K_2\|x-y\|^{\alpha/(1-\alpha)})
\end{align*}
In either case, the inequality holds for all $x,y$, so by taking $y\rightarrow x$ we attain the desired results.

Let $z_k,\gamma_k$ be sequences with $\gamma_k\geq \underline{\gamma}$ for all $k$.  Define the average iterate $\bar{z}_K=\frac{\sum_{k=0}^{K-1}\gamma_k z_k}{\sum_{k=0}^{K-1}\gamma_k}$. Then if $\bar{z}_K\in B$,   
    \begin{equation}
        \sup_{y\in B} \sum_{k=0}^{K-1} \gamma_k \left\langle F(y),z_k - y\right\rangle \geq K\underline{\gamma}\texttt{Gap}_{F,B}\left( \bar{z}_K\right)\label{Gap lemma}
    \end{equation}

\label{lem:unified predescent}
   For all $y\in U$, the iterates of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 and  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
 algorithms satisfy 
    \begin{equation}
    \begin{aligned}
        \|x_{k+1}-y\|^2 &\leq \|x_k-y\|^2 - \|x_{k+1}-\hat{x}_k\|^2-\|\hat{x}_k -x_k\|^2 \\
        &\qquad + 2\gamma_k\|F(\hat{x}_k)-F(\tilde{x}_k)\|\|x_{k+1}-\hat{x}_k\| - 2\gamma_k\left\langle F(\hat{x}_k),\hat{x}_k - y\right\rangle
    \end{aligned} \label{eg popov descent}
    \end{equation}
    where $\tilde{x}_k=\begin{cases}
        x_k &\text{ for  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
} \\
        \hat{x}_{k-1} &\text{ for  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
}
    \end{cases}$

Let $F$ be $\alpha$-symmetric $(L_0,L_1)$-Lipschitz. Then iterates of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 with stepsizes given by (\ref{EG Stepsizes}) with $\nu<1$ satisfy
        \begin{equation}
            \gamma_k\|F(x_k)-F(\hat{x}_k)\| \leq C_\nu \|x_k-\hat{x}_k\| \label{EG f bound}
        \end{equation}
        where $C_\nu=\nu e^\nu$ if $\alpha=1$ and $\nu$ if $\alpha \in(0,1)$.

First, note from the  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 algorithm definition and since $x_k\in U$, we have
        \begin{align}
            \|x_k-\hat{x}_k\|&=\|P_U(x_k)-P_U(x_k-\gamma_kF(x_k))\| \notag\\
            &\overset{(\ref{Nonexpansive})}{\leq} \gamma_k\|F(x_k)\|\label{EG half step f}
        \end{align}
      Now, starting with the case of $\alpha = 1$, we have
      \begin{align*}
          \gamma_k\|F(\hat{x}_k)-F(x_k)\|&\overset{(\ref{a1 l0l1})}{\leq} \gamma_k\|x_k-\hat{x}_k\|(L_0+L_1\|F(x_k)\|)\exp(L_1\|x_k-\hat{x}_k\|) \\
          &\overset{(\ref{EG Stepsizes})}{=} \nu\|x_k-\hat{x}_k\|\exp(L_1\|x_k-\hat{x}_k\|) \\
          &\overset{(\ref{EG half step f})}{\leq} \nu \|x_k-\hat{x}_k\|\exp(L_1\gamma_k\|F(x_k)\|) \\ 
          &\overset{(\ref{EG Stepsizes})}{=} \nu \|x_k-\hat{x}_k\|\exp\left( \frac{\nu L_1\|F(x_k)\|}{L_0+L_1\|F(x_k)\|} \right)\\
          &\overset{(\ref{EG Stepsizes})}{\leq} \nu e^\nu \|x_k-\hat{x}_k \|
      \end{align*}

    We now turn to $\alpha \in (0,1)$. We have 
    \begin{align*}
    \gamma_k\|F(\hat{x}_k)-F(x_k)\|
            &\overset{(\ref{a small l0l1})}{\leq} \gamma_k(K_0+K_1\|F(x_k)\|^\alpha + K_2(\gamma_k\|F(x_k)\|)^{\alpha/(1-\alpha)})\|\hat{x}_k-x_k\| \\ &= \left( \gamma_k(K_0+K_1\|F(x_k)\|^\alpha)+\gamma_k^{1/(1-\alpha)}K_2\|F(x_k)\|^{\alpha/(1-\alpha)} \right)\|\hat{x}_k-x_k\| \\
            &= \frac{\nu(K_0+K_1\|F(x_k)\|^\alpha)\|\hat{x}_k-x_k\|}{2K_0+(2K_1+2^{1-\alpha}K_2^{1-\alpha})\|F(x_k)\|^\alpha} \\
            &\qquad+ \frac{\nu^{1/(1-\alpha)}K_2\|F(x_k)\|^{\alpha/(1-\alpha)}\|\hat{x}_k-x_k\|}{(2K_0+(2K_1+2^{1-\alpha}K_2^{1-\alpha})\|F(x_k)\|^\alpha)^{1/(1-\alpha)}} \\
            &\leq \left( \frac{\nu}{2}+\frac{\nu^{1/(1-\alpha)}}{2} \right)\|\hat{x}_k-x_k\| \\
            &\leq \nu \|\hat{x}_k-x_k\|
        \end{align*}
    where the last step uses $\nu< 1$.

Let $F$ be $\alpha$-symmetric $(L_0,L_1)$-Lipschitz. Then iterates of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
 with stepsizes given by \eqref{Popov stepsizes} satisfy
        \begin{equation}
        \gamma_k\|F(\hat{x}_k)-F(\hat{x}_{k-1})\| \leq C_\nu\|\hat{x}_k-\hat{x}_{k-1} \|\label{popov f bound}
        \end{equation}
        where $C_\nu=\nu e^\nu$ if $\alpha=1$ and $\nu$ if $\alpha\in (0,1)$, and $\nu<1$.

First, note that by the projection inequality and the definition of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[PEG_update]{\color{PineGreen}\sfPEG} 
  \endgroup
  \xspace
, we have 
        \begin{align}
            \|\hat{x}_k-\hat{x}_{k-1}\|&=\|P_U(x_k-\gamma_kF(\hat{x}_{k-1}))-\hat{x}_{k-1}\| \notag\\
            &\overset{(\ref{Nonexpansive})}{\leq} \|x_k-\hat{x}_{k-1} - \gamma_kF(\hat{x}_{k-1})\|\notag \\
            &\leq \|x_k-\hat{x}_{k-1}\|+\gamma_k\|F(\hat{x}_{k-1})\|\label{popov half step diff}
        \end{align}
        We now treat each $\alpha$ separately. Starting with $\alpha = 1$:
            \begin{align}
            \gamma_k&\|F(\hat{x}_k)-F(\hat{x}_{k-1})\| \overset{(\ref{a1 l0l1})}{\leq} \gamma_k\|\hat{x}_k-\hat{x}_{k-1}\|(L_0+L_1\|F(\hat{x}_{k-1})\|)\exp(L_1\|\hat{x}_k-\hat{x}_{k-1}\|) \notag\\
            &\overset{(\ref{popov half step diff})}{\leq} \gamma_k\|\hat{x}_k-\hat{x}_{k-1}\|(L_0+L_1\|F(\hat{x}_{k-1})\|)\exp(L_1\|x_k-\hat{x}_{k-1}\|+L_1\gamma_k\|F(\hat{x}_{k-1})\|)\notag\\ 
            &\leq \gamma_k\|\hat{x}_k-\hat{x}_{k-1}\|(L_0+L_1\|F(\hat{x}_{k-1})\|)\exp(L_1\|x_k-\hat{x}_{k-1}\|+\nu)\notag\\
            &= \nu e^\nu\|\hat{x}_k-\hat{x}_{k-1}\| \label{f bound a1 popov}
        \end{align}
        Now, for $\alpha \in (0,1)$:
        \begin{align}
            \gamma_k &\|F(\hat{x}_k)-F(\hat{x}_{k-1})\| \overset{(\ref{a small l0l1})}{\leq} \gamma_k \|\hat{x}_k-\hat{x}_{k-1}\|\left( K_0+K_1\|F(\hat{x}_{k-1})\|^\alpha + K_2\|\hat{x}_k-\hat{x}_{k-1}\|^{\alpha/(1-\alpha)} \right)\notag\\
            &\overset{(\ref{popov half step diff})}{\leq} \resizebox{0.9\linewidth}{!}{$\gamma_k \|\hat{x}_k-\hat{x}_{k-1}\|\left( K_0+K_1\|F(\hat{x}_{k-1})\|^\alpha + K_2\left( \|x_k-\hat{x}_{k-1}\|+\gamma_k\|F(\hat{x}_{k-1})\| \right)^{\alpha/(1-\alpha)} \right)$}\notag\\
            &\leq \resizebox{0.925\linewidth}{!}{$\gamma_k \|\hat{x}_k-\hat{x}_{k-1}\|\left( K_0+K_1\|F(\hat{x}_{k-1})\|^\alpha + K_2\left( \|x_k-\hat{x}_{k-1}\|+\frac{\nu}{K_1}\|F(\hat{x}_{k-1})\|^{1-\alpha} \right)^{\alpha/(1-\alpha)} \right)$}\notag\\
