  \xspace
 with stepsizes given by (\ref{Popov stepsizes}) and $\nu$ chosen so that $C_\nu< 1$  satisfy $R_{k+1}\leq R_0$ for all $k\in 0,1,2,...$, we have
    \begin{equation}
        \gamma_k\geq\underline{\gamma}=\begin{cases}
            \frac{\nu}{(L_0+L_1(\sqrt{2}\|x_0-x^*\|(L_0+L_1\|F(x^*)\|)\exp(\sqrt{2}L_1\|x_0-x^*\|) + \|F(x^*)\|))\exp\left( \frac{\nu^2 e^\nu}{1-\nu e^\nu} \right)} &\text{ if $\alpha = 1$ }\\
            \frac{\nu}{K_0+\left( K_1 + K_2\left( \frac{\nu^2}{\left( K_1+K_2\left( \frac{\nu}{K_1} \right)^{\alpha/(1-\alpha)} \right)(1-\nu)}+\frac{\nu}{K_1} \right)^{\alpha/(1-\alpha)} \right)\overline{F}^{\alpha}} &\text{ if $\alpha \in (0,1)$ }
        \end{cases}\label{popov step lower bound}
    \end{equation}
        where $R_k=\|x_k-x^*\|^2+\|x_k-\hat{x}_{k-1}\|^2$  and $\overline{F}= \sqrt{2}\|x_0-x^*\|(K_0+K_1\|F(x^*)\|^\alpha+2^{\alpha/(2(1-\alpha))}K_2\|x_0-x^*\|^{\alpha/(1-\alpha)}) + \|F(x^*)\|$.

To lower bound our stepsizes, we must upper bound each of $\|F(\hat{x}_{k-1})\|$ and $\|x_k-\hat{x}_{k-1}\|$. Starting with upper bounding $\|F(\hat{x}_{k-1})\|$, we have by the definition of $R_k$ and by initializing the algorithm with $\hat{x}_{-1}=x_0$ that
    \begin{equation}
        \|x_k-x^*\|^2+\|x_k-\hat{x}_{k-1}\|^2 \leq \|x_0-x^*\|^2 \label{popov descent exp}
    \end{equation}
    and similarly,
    \begin{align}
        \|\hat{x}_{k-1} - x^*\|^2 &\overset{(\ref{young ineq})}{\leq} 2\|x_k-x^*\|^2 +2 \|x_k-\hat{x}_{k-1}\|^2 \notag\\
        &\overset{(\ref{popov descent exp})}{\leq} 2\|x_0-x^*\|^2 \label{popov half from sol}
    \end{align}

    We now treat the cases of $\alpha=1$ and $\alpha\in (0,1)$ separately. In the case of $\alpha=1$, we have
    \begin{align}
        \|F(\hat{x}_{k-1})\|&\leq \|F(\hat{x}_{k-1})-F(x^*)\|+\|F(x^*)\| \notag\\
        &\overset{(\ref{a1 l0l1})}{\leq} \|\hat{x}_{k-1}-x^*\|(L_0+L_1\|F(x^*)\|)\exp(L_1\|\hat{x}_{k-1}-x^*\|) + \|F(x^*)\|\notag \\
        &\overset{(\ref{popov half from sol})}{\leq} \sqrt{2}\|x_0-x^*\|(L_0+L_1\|F(x^*)\|)\exp(\sqrt{2}L_1\|x_0-x^*\|) + \|F(x^*)\| \label{popov final f bound a1}
    \end{align}
    As for when $\alpha \in (0,1)$,
    \begin{align}
        \|F&(\hat{x}_{k-1})\|\leq \|F(\hat{x}_{k-1})-F(x^*)\|+\|F(x^*)\| \notag\\
        &\overset{(\ref{a small l0l1})}{\leq} \|\hat{x}_{k-1}-x^*\|(K_0+K_1\|F(x^*)\|^\alpha+K_2\|\hat{x}_{k-1}-x^*\|^{\alpha/(1-\alpha)}) + \|F(x^*)\| \notag\\
        &\overset{(\ref{popov half from sol})}{\leq} \sqrt{2}\|x_0-x^*\|(K_0+K_1\|F(x^*)\|^\alpha+2^{\alpha/(2(1-\alpha))}K_2\|x_0-x^*\|^{\alpha/(1-\alpha)}) + \|F(x^*)\|\notag\\
        &=\overline{F} \label{popov final f bound asmall}
    \end{align}
    With these bounds on our operator norms established, we move onto bounding $\|x_k-\hat{x}_{k-1}\|$.  We have for any value of $\alpha$ that
    \begin{align}
        \|x_k-\hat{x}_{k-1}\| &\overset{(\ref{Nonexpansive})}{\leq} \gamma_{k-1}\|F(\hat{x}_{k-1})-F(\hat{x}_{k-2})\| \notag\\
        &\overset{(\ref{popov f bound})}{\leq} C_{\nu}\|\hat{x}_{k-1}-\hat{x}_{k-2}\| \notag\\
        &\overset{(\ref{popov half step diff})}{\leq} C_{\nu}\left( \|x_{k-1}-\hat{x}_{k-2}\|+\gamma_{k-1}\|F(\hat{x}_{k-2})\| \right) \label{popov half step bound intermediate}
        \end{align}
    We now must bound $\gamma_{k-1}\|F(\hat{x}_{k-2})\|$ separately for each $\alpha$. In the case where $\alpha=1$, we have
    \begin{align*}
            \gamma_{k-1}\|F(\hat{x}_{k-2})\| &= \frac{\nu \|F(\hat{x}_{k-2})\|}{(L_0+L_1\|F(\hat{x}_{k-2})\|)\exp(L_1\|x_{k-1}-\hat{x}_{k-2}\|)} \\
            &\leq \frac{\nu}{L_1}
    \end{align*}
    and similarly for $\alpha \in (0,1)$, we have
    \begin{align*}
     \gamma_{k-1}\|F(\hat{x}_{k-2})\| &=   \frac{\nu\|F(\hat{x}_{k-2})\|}{K_0+K_1\|F(\hat{x}_{k-2})\|^\alpha + K_2(\|x_{k-1}-\hat{x}_{k-2}\|+\frac{\nu}{K_1}\|F(\hat{x}_{k-2})\|^{1-\alpha})^\frac{\alpha}{1-\alpha}} \\
     &\leq \frac{\nu\|F(\hat{x}_{k-2})\|}{\left( K_1+K_2\left( \frac{\nu}{K_1} \right)^{\alpha/(1-\alpha)} \right)\|F(\hat{x}_{k-2})\|^\alpha} \\
     &=\frac{\nu \|F(\hat{x}_{k-2})\|^{1-\alpha}}{K_1+K_2\left( \frac{\nu}{K_1} \right)^{\alpha/(1-\alpha)}} \\
     &\leq \frac{\nu \overline{F}^{1-\alpha} }{K_1+K_2\left( \frac{\nu}{K_1} \right)^{\alpha/(1-\alpha)}}
    \end{align*}

    Defining $M=\begin{cases}
        \frac{\nu}{L_1}\text{ if $\alpha = 1$ } \\
        \frac{\nu \overline{F}^{1-\alpha}}{K_1+K_2\left( \frac{\nu}{K_1} \right)^{\alpha/(1-\alpha)}} \text{ if $\alpha \in (0,1)$ }
    \end{cases}$ we have from (\ref{popov half step bound intermediate}) 

    \begin{equation*}
        \|x_k-\hat{x}_{k-1}\| \leq  C_{\nu}\left( \|x_{k-1}-\hat{x}_{k-2}\|+M \right) 
    \end{equation*}
    We then unwind the recursion:
    \begin{align}
      \|x_k-\hat{x}_{k-1}\|  &\leq C_{\nu}^k\|x_0-\hat{x}_{-1}\|+\sum_{i=1}^k MC_\nu^i\notag\\
      &= M\sum_{i=1}^k C_\nu^i \notag\\
      &\leq \frac{MC_\nu}{1-C_\nu}\notag\\
        &=\begin{cases}
            \frac{\nu^2 e^\nu}{L_1(1-\nu e^\nu)}\text{ if $\alpha = 1$ } \\
            \frac{\nu^2 \overline{F}^{1-\alpha} }{\left( K_1+K_2\left( \frac{\nu}{K_1} \right)^{\alpha/(1-\alpha)} \right)(1-\nu)} \text{ if $\alpha \in (0,1)$ }
        \end{cases} \label{popov half step bound} 
    \end{align}
    where in the second to last line we used that $C_\nu<1$. 

    Now that we have upper bounded both $\|F(\hat{x}_{k-1})\|$ and $\|x_k-\hat{x}_{k-1}\|$, we can lower bound our stepsizes.

    For $\alpha=1$, we have
    \begin{align*}
        \gamma_k&=\frac{\nu}{(L_0+L_1\|F(\hat{x}_{k-1})\|)\exp(L_1\|x_k-\hat{x}_{k-1}\|)} \\
        &\overset{(\ref{popov half step bound})}{\geq} \frac{\nu}{(L_0+L_1\|F(\hat{x}_{k-1})\|)\exp\left( \frac{\nu^2 e^\nu}{1-\nu e^\nu} \right)} \\
        &\overset{(\ref{popov final f bound a1})}{\geq} \resizebox{0.9\linewidth}{!}{$\frac{\nu}{(L_0+L_1(\sqrt{2}\|x_0-x^*\|(L_0+L_1\|F(x^*)\|)\exp(\sqrt{2}L_1\|x_0-x^*\|) + \|F(x^*)\|))\exp\left( \frac{\nu^2 e^\nu}{1-\nu e^\nu} \right)}$}
    \end{align*}
    While for $\alpha \in (0,1)$, we find 
    \begin{align*}
        \gamma_k &=\frac{\nu}{K_0+K_1\|F(\hat{x}_{k-1})\|^\alpha + K_2(\|x_k-\hat{x}_{k-1}\|+\frac{\nu}{K_1}\|F(\hat{x}_{k-1})\|^{1-\alpha})^\frac{\alpha}{1-\alpha}} \\
        &\overset{(\ref{popov final f bound asmall})}{\geq} \frac{\nu}{K_0+K_1\overline{F}^\alpha + K_2\left( \|x_k-\hat{x}_{k-1}\|+\frac{\nu}{K_1}\overline{F}^{1-\alpha} \right)^\frac{\alpha}{1-\alpha}}\\
        &\overset{(\ref{popov half step bound})}{\geq} \frac{\nu}{K_0+\left( K_1 + K_2\left( \frac{\nu^2}{\left( K_1+K_2\left( \frac{\nu}{K_1} \right)^{\alpha/(1-\alpha)} \right)(1-\nu)}+\frac{\nu}{K_1} \right)^\frac{\alpha}{1-\alpha} \right)\overline{F}^{\alpha}}
    \end{align*}

\label{lem: eg descent}
