    \end{equation}
      where $y\in U$, $\beta>0$, and $R_k(y)=\|x_k-y\|^2+\|x_k-\hat{x}_{k-1}\|^2$.

Let $F$ be $\alpha$-symmetric $(L_0, L_1)$-Lipschitz and monotone. Additionally let $\bar{x}_K=\frac{\sum_{k=0}^{K-1}\gamma_k\hat{x}_k}{\sum_{k=0}^{K-1}\gamma_k}$ and $x^*\in U^*$. Then the averaged iterates $\bar{x}_K$ of  
  \begingroup
  \hypersetup{linkcolor=PineGreen} 
  \hyperref[EG_update]{\color{PineGreen}\sfEG} 
  \endgroup
  \xspace
 with stepsizes given by (\ref{EG Stepsizes}) and $\nu$ chosen so that $C_\nu< 1$  satisfy
         \begin{equation*}
          \texttt{Gap}_{F,B}\left( \bar{x}_K\right)\leq \left( 2+\frac{1}{\sqrt{1-C_\nu^2}} \right)^2\frac{\|x_0-x^*\|^2}{2\underline{\gamma} K}
        \end{equation*}
