We are largely able to reuse our proof of Lemma~\ref{lem:popov step lower bound}. From our assumption that $R_{k+1}\leq R_0$, we have
    \begin{equation}
        \|x_k-x^*\|^2+\|x_k-\hat{x}_{k-1}\|^2\leq \|x_0-x^*\|^2 \label{adapeg step lower bound 1}
    \end{equation}
 From the same reasoning as in the proof of Lemma~\ref{lem:popov step lower bound}, we have that Equation \ref{popov final f bound a1} applies to {\color{PineGreen}\sfPEG-LS}\xspace:
    \begin{equation}
       \|F(\hat{x}_{k-1})\|\leq \sqrt{2}\|x_0-x^*\|(L_0+L_1\|F(x^*)\|)\exp(\sqrt{2}L_1\|x_0-x^*\|) + \|F(x^*)\| \label{adapeg f bound}
    \end{equation}

    Lastly, we must bound $\|x_k-\hat{x}_{k-1}\|$. We derive two distinct bounds and take the minima between them. For the first bound, we can use a similar telescoping argument to the proof of Lemma~\ref{lem:popov step lower bound}. Specifically, we again have,
    \begin{align}
        \|x_k-\hat{x}_{k-1}\| &\overset{(\ref{Nonexpansive})}{\leq} \gamma_{k-1}\|F(\hat{x}_{k-1})-F(\hat{x}_{k-2})\| \notag\\
        &\leq \nu e^\nu\|\hat{x}_{k-1}-\hat{x}_{k-2}\| \notag\\
        &\overset{(\ref{popov half step diff})}{\leq} \nu e^\nu \left( \|x_{k-1}-\hat{x}_{k-2}\|+\gamma_{k-1}\|F(\hat{x}_{k-2})\| \right) \notag
    \end{align}
    where the second inequality is a result of our backtracking condition. Then since $\lambda_k^1\geq \lambda_{-1}^1$ for all $k$, we have
    \begin{align*}
            \gamma_{k-1}\|F(\hat{x}_{k-2})\| &= \frac{\nu \|F(\hat{x}_{k-2})\|}{(\lambda_{k-1}^0+\lambda_{k-1}^1\|F(\hat{x}_{k-2})\|)\exp(\lambda_{k-1}^1\|x_{k-1}-\hat{x}_{k-2}\|)} \\
            &\leq \frac{\nu}{\lambda_{-1}^1}
    \end{align*}
    We thus obtain the recursion of 
    \begin{equation*}
        \|x_k-\hat{x}_{k-1}\|\leq \nu e^\nu \left( \|x_{k-1}-\hat{x}_{k-2}\|+\frac{\nu}{\lambda_{-1}^1} \right)
    \end{equation*}
    Unwinding this in the same manner as in the proof of Lemma~\ref{lem:popov step lower bound}, we find
    $$\|x_k-\hat{x}_{k-1}\|\leq \frac{\nu^2 e^\nu}{\lambda^1_{-1}(1-\nu e^\nu)}$$.

    For the second bound, we use a simple but somewhat more crude result from \eqref{adapeg step lower bound 1} of
    \begin{equation*}
        \|x_k-\hat{x}_{k-1}\|^2\leq \|x_0-x^*\|^2 
    \end{equation*}
     This bound in particular may be tighter when we use a small initial estimate $\lambda_{-1}^1$ for $L_1$.

    Combining the above two bounds, we define $M=\min\left\{\|x_0-x^*\|, \frac{\nu^2 e^\nu}{\lambda^1_{-1}(1-\nu e^\nu)}\right\}$ and thus obtain
    \begin{equation}
        \|x_k-\hat{x}_{k-1}\|\le M  \label{adapeg halfstep bound}
    \end{equation}

Putting all of our bounds together, we conclude that for all $k$,
\begin{align*}
    \gamma_k &=\frac{\nu}{({\lambda}_k^0+{\lambda}_k^1\|F(\hat{x}_{k-1})\|)\exp({\lambda}_k^1\|x_k-\hat{x}_{k-1}\|)}\\
